// message-event metadata, outbound provenance, template-authority verdict and pre-claim
// verdict must be EXACTLY what the production base (6ecbae6b) produced. The golden file
// tests/fixtures/origin-byte-identity.golden.json was generated by running computeSnapshots()
// against the base tree's modules (see the test header); the test recomputes it on HEAD.
// Imports nothing from src: the caller passes the module namespaces in.
export const NOW = '2026-10-15T15:00:00.000Z'

const tpl = { id: 'b1f3c2d4-0000-4000-8000-000000000001', template_id: 'tmpl-own-1', use_case: 'ownership_check', is_active: true, template_body: 'Hi {{seller_first_name}}, this is {{agent_name}}. Do you still own {{property_address}}?' }

export const FIXTURE_ROWS = Object.freeze([
  ['campaign_launch', { queue_key: 'campaign:c1:t1', queue_status: 'queued', message_body: 'Hi Sam, this is Helen. Do you still own 12 Elm St?', to_phone_number: '+15555550101', from_phone_number: '+15555550199', thread_key: '+15555550101', template_id: 'tmpl-own-1', selected_template_id: 'tmpl-own-1', template_key: 'tmpl-own-1', template_source: 'sms_templates', use_case_template: 'ownership_check', message_type: 'outbound', type: 'campaign_launch', source: 'campaign_launch_execution', campaign_id: 'c1', campaign_target_id: 't1', property_id: 'p1', master_owner_id: 'mo1', prospect_id: 'pr1', seller_first_name: 'Sam', agent_name: 'Helen', touch_number: 1, metadata: { source: 'campaign_launch_execution', agent_persona: 'Helen', candidate_snapshot: { canonical_property_group: 'sfr' } } }],
  ['auto_reply_template', { queue_key: 'inbound_auto_reply:evt1:tmpl-int-1:+15555550102', queue_status: 'queued', message_body: 'Thanks Pat. Would you consider an offer on it?', to_phone_number: '+15555550102', from_phone_number: '+15555550199', thread_key: '+15555550102', template_id: 'tmpl-int-1', selected_template_id: 'tmpl-int-1', template_source: 'sms_templates', use_case_template: 'consider_selling', message_type: 'Follow-Up', type: 'auto_reply', source_event_id: 'evt1', inbound_message_id: 'evt1', seller_first_name: 'Pat', metadata: { source: 'auto_reply', action_type: 'autopilot_inbound_reply', decision_id: 'evt1', candidate_snapshot: {} } }],
  ['followup_catalog', { queue_key: 'followup:s2:evt2', queue_status: 'scheduled', message_body: 'Hi Lee, just a quick follow up on 4 Oak.', to_phone_number: '+15555550103', from_phone_number: '+15555550199', thread_key: '+15555550103', template_id: 'tmpl-fu-1', use_case_template: 's2_no_response_fu1', message_type: 'followup', type: 'followup', seller_first_name: 'Lee', metadata: { source: 'no_response_followup', candidate_snapshot: {} } }],
  ['operator_manual', { queue_key: 'inbox:send_now:1', queue_status: 'queued', message_body: 'Hey, sorry I missed your call. Still around?', to_phone_number: '+15555550104', from_phone_number: '+15555550199', thread_key: '+15555550104', template_source: 'manual_composer', message_type: 'manual_reply', type: 'outbound', metadata: { source: 'manual_inbox', action: 'send_now', created_from: 'leadcommand_inbox' } }],
  ['workflow_v2', { queue_key: 'wf:1', queue_status: 'queued', message_body: 'Hi Jo, checking in on 9 Pine.', to_phone_number: '+15555550105', from_phone_number: '+15555550199', thread_key: '+15555550105', metadata: { source: 'workflow_v2', template_id: 'tmpl-wf-1' } }],
])

const clone = (x) => JSON.parse(JSON.stringify(x))

/**
 * @param {{ smsEngine: object, provenance: object, templateAuthority: object }} m module namespaces
 */
export async function computeSnapshots(m) {
  const out = {}
  for (const [name, row] of FIXTURE_ROWS) {
    let captured = null
    await m.smsEngine.insertSupabaseSendQueueRow(clone(row), { now: NOW, insertSupabaseSendQueueRow: (p) => { captured = p; return { ok: true, queue_row_id: 'q-1', raw: p } } })
    const ev = m.smsEngine.buildSuccessMessageEvent({ id: 'b1f3c2d4-0000-4000-8000-0000000000aa', ...clone(row), queue_status: 'sent' }, { sid: 'SMfixture', status: 'accepted' }, { now: NOW })
    const prov = m.provenance.buildOutboundProvenance(clone(row))
    const client = { from: () => ({ select: () => ({ eq: () => ({ limit: async () => ({ data: [tpl] }) }) }) }) }
    const ta = await m.templateAuthority.evaluateTemplateAuthority({ queue_row: clone(row), supabase: client, manual_operator_send: row.metadata?.source === 'manual_inbox' })
    out[name] = { insert_payload: captured, success_event_metadata: ev?.metadata ?? null, success_event_template_id: ev?.template_id ?? null, provenance: prov, template_authority: ta }
  }
  // pre-claim verdicts for the same rows (runnable vs skipped + reason)
  const rows = FIXTURE_ROWS.map(([name, row], i) => ({ ...clone(row), id: `b1f3c2d4-0000-4000-8000-00000000010${i}`, created_at: NOW, scheduled_for: NOW, scheduled_for_utc: NOW, queue_status: 'queued' }))
  const sb = m.makeSendQueueRowsSupabase(rows)
  const pre = await m.smsEngine.loadRunnableSendQueueRows(20, { now: NOW, stale_lock_recovery_enabled: false, supabaseClient: sb, getSystemValue: async () => null, pauseInvalidQueueRow: async (n, p) => ({ ...n, ...p }) })
  out.__preclaim = { runnable: pre.rows.map((r) => r.id).sort(), skipped: pre.skipped.map((s) => [s.id, s.reason]).sort() }
  return JSON.parse(JSON.stringify(out))
}
